CREATE OR REPLACE FUNCTION public.accept_my_staff_invitation() RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE i public.staff_invitations;email text:=lower(auth.jwt()->>'email');BEGIN IF auth.uid() IS NULL OR email IS NULL THEN RETURN false;END IF;SELECT * INTO i FROM public.staff_invitations WHERE staff_invitations.email=email AND status='sent' AND expires_at>now() ORDER BY created_at DESC LIMIT 1 FOR UPDATE;IF NOT FOUND THEN RETURN false;END IF;IF NOT EXISTS(SELECT 1 FROM public.roles WHERE code=i.role AND is_active) THEN RAISE EXCEPTION 'الدور موقوف';END IF;UPDATE public.user_role_assignments SET is_active=false WHERE user_id=auth.uid();UPDATE public.user_roles SET is_active=false WHERE user_id=auth.uid();INSERT INTO public.user_role_assignments(user_id,role,assigned_by,reason) VALUES(auth.uid(),i.role,i.invited_by,'قبول دعوة موظف') ON CONFLICT(user_id,role) DO UPDATE SET is_active=true,assigned_by=excluded.assigned_by,assigned_at=now();UPDATE public.staff_invitations SET status='accepted',accepted_by=auth.uid(),accepted_at=now() WHERE id=i.id;PERFORM public._safety_audit('STAFF_INVITATION_ACCEPTED','staff_invitations',i.id::text,NULL,jsonb_build_object('role',i.role),'قبول دعوة موظف');RETURN true;END $$;
REVOKE ALL ON FUNCTION public.accept_my_staff_invitation() FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.accept_my_staff_invitation() TO authenticated;
CREATE TABLE IF NOT EXISTS public.contract_draft_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),opportunity_id uuid NOT NULL REFERENCES public.opportunities(id),party_id uuid NOT NULL REFERENCES public.parties(id),prepared_by uuid NOT NULL,status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','submitted','archived')),unit_ids uuid[] NOT NULL,notes text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());GRANT SELECT ON public.contract_draft_requests TO authenticated;GRANT ALL ON public.contract_draft_requests TO service_role;ALTER TABLE public.contract_draft_requests ENABLE ROW LEVEL SECURITY;CREATE POLICY draft_request_read ON public.contract_draft_requests FOR SELECT TO authenticated USING(public.has_permission('contracts.draft','edit') OR (public.has_permission('contracts.draft','own') AND prepared_by=auth.uid() AND EXISTS(SELECT 1 FROM public.opportunities o WHERE o.id=opportunity_id AND o.owner_user_id=auth.uid() AND o.outcome IS NULL)));
CREATE OR REPLACE FUNCTION public.prepare_contract_draft(_opportunity uuid,_units uuid[],_notes text,_reason text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o public.opportunities;k uuid:=gen_random_uuid();BEGIN PERFORM public._assert_reason(_reason);SELECT * INTO o FROM public.opportunities WHERE id=_opportunity FOR UPDATE;IF NOT FOUND OR o.outcome IS NOT NULL OR NOT(public.has_permission('contracts.draft','edit') OR(public.has_permission('contracts.draft','own') AND o.owner_user_id=auth.uid())) THEN RAISE EXCEPTION 'مسودة العقد لفرصك فقط';END IF;IF cardinality(_units) IS NULL OR cardinality(_units)=0 OR cardinality(_units)>100 OR EXISTS(SELECT 1 FROM unnest(_units) u WHERE NOT EXISTS(SELECT 1 FROM public.units x WHERE x.id=u AND NOT x.is_test)) OR length(coalesce(_notes,''))>2000 THEN RAISE EXCEPTION 'بيانات المسودة غير صالحة';END IF;INSERT INTO public.contract_draft_requests(id,opportunity_id,party_id,prepared_by,unit_ids,notes) VALUES(k,o.id,o.party_id,auth.uid(),_units,_notes);PERFORM public._safety_audit('CONTRACT_DRAFT_PREPARED','contract_draft_requests',k::text,NULL,jsonb_build_object('opportunity_id',o.id,'unit_ids',_units),_reason);RETURN k;END $$;
REVOKE ALL ON FUNCTION public.prepare_contract_draft(uuid,uuid[],text,text) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.prepare_contract_draft(uuid,uuid[],text,text) TO authenticated;
SELECT to_regclass('public.contract_draft_requests') IS NOT NULL AS draft_ready;